    def test_key_hash_override_cannot_interrupt_commit(self):
        for use_batch in [False, True]:
            with self.subTest(batch=use_batch):
                key = LateHashFailure(f'hash-{use_batch}')
                operation = {'source': 'a', 'target': 'b', 'amount': 1, 'key': key}
