    def test_batch_rejects_non_string_field_names_that_compare_equal(self):
        self.ledger.transfer('a', 'b', 1, 'existing')
        valid = {'source': 'a', 'target': 'c', 'amount': 1, 'key': 'new'}
        for field in valid:
